package text

import "testing"

func TestWords(t *testing.T) {
	if len(Words("a b  c")) != 3 {
		t.Fatal("expected three words")
	}
}

func TestWrap(t *testing.T) {
	tests := []struct {
		text   string
		width  int
		want   []string
	}{
		{
			text:  "",
			width: 10,
			want:  nil,
		},
		{
			text:  "   ",
			width: 5,
			want:  nil,
		},
		{
			text:  "hello world",
			width: 10,
			want:  []string{"hello", "world"},
		},
		{
			text:  "hello world",
			width: 20,
			want:  []string{"hello world"},
		},
		{
			text:  "short",
			width: 10,
			want:  []string{"short"},
		},
		{
			text:  "superlongword",
			width: 5,
			want:  []string{"superlongword"},
		},
		{
			text:  "a b c d e f g h i j k l m n o p q r s t u v w x y z",
			width: 10,
			want:  []string{"a b c d", "e f g h", "i j k l", "m n o p", "q r s t", "u v w x", "y z"},
		},
		{
			text:  "  multiple   spaces here ",
			width: 15,
			want:  []string{"multiple spaces", "here"},
		},
		{
			text:  "test",
			width: 0,
			want:  nil,
		},
		{
			text:  "test",
			width: -3,
			want:  nil,
		},
	}

	for _, tc := range tests {
		got := Wrap(tc.text, tc.width)
		if !equal(got, tc.want) {
			t.Errorf("Wrap(%q, %d) = %v; want %v", tc.text, tc.width, got, tc.want)
		}
	}
}

func equal(a, b []string) bool {
	if a == nil && b == nil {
		return true
	}
	if (a == nil) != (b == nil) {
		return false
	}
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

